-- Supprime les données de démonstration dépendantes puis les comptes insérés
-- directement dans auth.users (ils manquaient de la ligne auth.identities
-- requise par GoTrue). Ils seront recréés proprement via l'API Admin Supabase.
delete from public.reviews where doctor_id in (
  '00000000-0000-0000-0000-000000000011'
);
delete from public.appointments where id = '00000000-0000-0000-0000-000000000101';
delete from public.medical_profiles where patient_id = '00000000-0000-0000-0000-000000000002';
delete from public.doctors where id in (
  '00000000-0000-0000-0000-000000000010',
  '00000000-0000-0000-0000-000000000011',
  '00000000-0000-0000-0000-000000000012',
  '00000000-0000-0000-0000-000000000013',
  '00000000-0000-0000-0000-000000000014',
  '00000000-0000-0000-0000-000000000015'
);
delete from public.profiles where id in (
  '00000000-0000-0000-0000-000000000001',
  '00000000-0000-0000-0000-000000000002',
  '00000000-0000-0000-0000-000000000010',
  '00000000-0000-0000-0000-000000000011',
  '00000000-0000-0000-0000-000000000012',
  '00000000-0000-0000-0000-000000000013',
  '00000000-0000-0000-0000-000000000014',
  '00000000-0000-0000-0000-000000000015'
);
delete from auth.users where id in (
  '00000000-0000-0000-0000-000000000001',
  '00000000-0000-0000-0000-000000000002',
  '00000000-0000-0000-0000-000000000010',
  '00000000-0000-0000-0000-000000000011',
  '00000000-0000-0000-0000-000000000012',
  '00000000-0000-0000-0000-000000000013',
  '00000000-0000-0000-0000-000000000014',
  '00000000-0000-0000-0000-000000000015'
);
